import cirq


def qaoa_maxcut_ansatz(G, beta, gamma):
    if G is None:
        edges = ((0, 3), (0, 4), (1, 3), (1, 4), (2, 3), (2, 4))
        n_qubits = 5
    else:
        edges = tuple(G.edges)
        n_qubits = len(G.nodes)
    if beta is None:
        beta = [0.0] * 5
    if gamma is None:
        gamma = [0.0] * len(beta)

    q = cirq.LineQubit.range(n_qubits)
    circuit = cirq.Circuit()
    circuit.append(cirq.H.on_each(q))
    for layer, beta_value in enumerate(beta):
        gamma_value = gamma[layer]
        for control, target in edges:
            circuit.append(cirq.CNOT(q[control], q[target]))
            circuit.append(cirq.rz(2 * gamma_value).on(q[target]))
            circuit.append(cirq.CNOT(q[control], q[target]))
        for qubit in range(n_qubits):
            circuit.append(cirq.rx(2 * beta_value).on(q[qubit]))
    circuit.append(cirq.measure(q[4], q[3], q[2], q[1], q[0], key="result"))
    return circuit

