def shor_7mod15():
    q = cirq.LineQubit.range(12)
    circuit = cirq.Circuit()
    for c in range(8):
        circuit.append(cirq.H(q[c]))
    circuit.append(cirq.X(q[8]))

    def mult(control):
        yield cirq.SWAP(q[8], q[9]).controlled_by(control)
        yield cirq.SWAP(q[9], q[10]).controlled_by(control)
        yield cirq.SWAP(q[10], q[11]).controlled_by(control)
        for w in (8, 9, 10, 11):
            yield cirq.X(q[w]).controlled_by(control)

    for j in range(8):
        for _ in range(2 ** j):
            circuit.append(mult(q[j]))
    circuit.append(cirq.qft(*[q[i] for i in reversed(range(8))], inverse=True))
    circuit.append(cirq.measure(*[q[i] for i in reversed(range(8))], key="result"))
    return circuit

