def QCL_circuit():
    n_qubits = 3
    depth = 2
    weights = [
            [[(9 * d + 3 * i + k + 1) * math.pi / 19 for k in range(3)] for i in range(n_qubits)]
            for d in range(depth)
        ]
    q = cirq.LineQubit.range(n_qubits)
    circuit = cirq.Circuit()
    for d in range(depth):
        for i in range(n_qubits - 1):
            circuit.append(cirq.CNOT(q[i], q[i + 1]))
        circuit.append(cirq.CNOT(q[n_qubits - 1], q[0]))
        for i in range(n_qubits):
            circuit.append(cirq.rx(weights[d][i][0]).on(q[i]))
            circuit.append(cirq.rz(weights[d][i][1]).on(q[i]))
            circuit.append(cirq.rx(weights[d][i][2]).on(q[i]))
    return circuit

