    circuit = cirq.Circuit()

    def controlled_z_all():
        circuit.append(cirq.H(q[2]))
        circuit.append(cirq.CCX(q[0], q[1], q[2]))
        circuit.append(cirq.H(q[2]))

    def phase_mark(bitstring):
        for qubit, bit in ((2, bitstring[0]), (1, bitstring[1]), (0, bitstring[2])):
            if bit == "0":
                circuit.append(cirq.X(q[qubit]))
        controlled_z_all()
        for qubit, bit in ((2, bitstring[0]), (1, bitstring[1]), (0, bitstring[2])):
            if bit == "0":
                circuit.append(cirq.X(q[qubit]))

    for qubit in range(3):
        circuit.append(cirq.H(q[qubit]))
    phase_mark("010")
    phase_mark("101")
    for qubit in range(3):
        circuit.append(cirq.H(q[qubit]))
        circuit.append(cirq.X(q[qubit]))
