def quantum_counting_marked_11():
    q = cirq.LineQubit.range(5)
    circuit = cirq.Circuit()

    def controlled_h(control, target):
        circuit.append(cirq.S(q[target]))
        circuit.append(cirq.H(q[target]))
        circuit.append(cirq.T(q[target]))
        circuit.append(cirq.CNOT(q[control], q[target]))
        for _ in range(7):
            circuit.append(cirq.T(q[target]))
        circuit.append(cirq.H(q[target]))
        for _ in range(3):
            circuit.append(cirq.S(q[target]))

    def controlled_cz(control, a, b):
        circuit.append(cirq.H(q[b]))
        circuit.append(cirq.TOFFOLI(q[control], q[a], q[b]))
        circuit.append(cirq.H(q[b]))

    def controlled_grover(control):
        controlled_cz(control, 3, 4)
        for target in (3, 4):
            controlled_h(control, target)
        circuit.append(cirq.CNOT(q[control], q[3]))
        circuit.append(cirq.CNOT(q[control], q[4]))
        controlled_cz(control, 3, 4)
        circuit.append(cirq.CNOT(q[control], q[3]))
        circuit.append(cirq.CNOT(q[control], q[4]))
        for target in (3, 4):
            controlled_h(control, target)

    def cp(angle, control, target):
        circuit.append(cirq.CZPowGate(exponent=angle / math.pi).on(q[control], q[target]))

    def inverse_qft(qubits):
        n = len(qubits)
        for i in range(n // 2):
            circuit.append(cirq.SWAP(q[qubits[i]], q[qubits[n - 1 - i]]))
        for i in range(n):
            for j in range(i):
                cp(-math.pi / (2 ** (i - j)), qubits[j], qubits[i])
            circuit.append(cirq.H(q[qubits[i]]))

    for qubit in range(5):
        circuit.append(cirq.H(q[qubit]))
    for control in range(3):
        for _ in range(2 ** control):
            controlled_grover(control)
            circuit.append(cirq.Z(q[control]))
    inverse_qft([0, 1, 2])
    circuit.append(cirq.measure(q[2], q[1], q[0], key="result"))
    return circuit

