def spectral_sum_phase_estimation():
    q = cirq.LineQubit.range(5)
    circuit = cirq.Circuit()

    def cp(angle, control, target):
        circuit.append(cirq.CZPowGate(exponent=angle / math.pi).on(q[control], q[target]))

    def inverse_qft(qubits):
        n = len(qubits)
        for i in range(n // 2):
            circuit.append(cirq.SWAP(q[qubits[i]], q[qubits[n - 1 - i]]))
        for i in range(n):
            for j in range(i):
                cp(-math.pi / (2 ** (i - j)), qubits[j], qubits[i])
            circuit.append(cirq.H(q[qubits[i]]))

    for qubit in (0, 1, 2, 3, 4):
        circuit.append(cirq.H(q[qubit]))
    for control in range(3):
        scale = 2 ** control
        cp(-math.pi / 4 * scale, control, 3)
        cp(-math.pi / 2 * scale, control, 4)
    inverse_qft([0, 1, 2])
    circuit.append(cirq.measure(q[2], q[1], q[0], key="result"))
    return circuit
